def cp(code):
    try:
        compile(code, '<probe>', 'exec')
        return dict(accepted=True)
    except (SyntaxError, ValueError) as e:
        return dict(accepted=False, exception=type(e).__name__, message=str(e), line=getattr(e,'lineno',None))

def native(code, name, home):
    p=OUT/(name+'.py');p.write_text(code)
