    valid=['_', 'a', 'None', 'True', 'False', '1 | 2', '[a, *rest]', '(a, b)', '{"x": a, **rest}', 'C(a, key=b)', '(1 | 2) as a', '[a] | (a,)', '{b"x": a, "x": b}', '1+2j', '-1-2j', 'C.VALUE']
