    for i,s in enumerate(valid):cases['valid-pattern-'+str(i)]=(pat(s),True)
    for i,s in enumerate(invalid):cases['invalid-pattern-'+str(i)]=(pat(s),False)
    cases['unreachable-case']=('def unused(x):\n    match x:\n        case _:\n            pass\n        case 1:\n            pass\n',False)
    cases['guarded-capture']=('def unused(x):\n    match x:\n        case a if a > 0:\n            pass\n        case _:\n            pass\n',True)
    for bits in [64,1000,4001,14285,15000]:
        v=1<<bits
